   const before=await db.$queryRaw`SELECT "id","amount","sessionId","paymentMethod","subtractFromShift" FROM "StoreTransaction" ORDER BY "id"`,shifts=await db.$queryRaw`SELECT * FROM "CashShiftSession" ORDER BY "id"`,jobs=(await db.$queryRaw`SELECT COUNT(*)::int n FROM "AiReaderJob"`)[0].n;
