   const captured=await post(path,request);assert.equal(captured.status,201,JSON.stringify(captured));assert.equal(captured.body.sourceKind,'PLAIN_CAPTURE');const retry=await post(path,request);assert.equal(retry.status,200);assert.equal(retry.body.proofId,captured.body.proofId);assert.equal((await readPendingInvoices(db,scoped)).count,0);
   assert.deepEqual(await db.$queryRaw`SELECT "id","amount","sessionId","paymentMethod","subtractFromShift" FROM "StoreTransaction" ORDER BY "id"`,before);assert.deepEqual(await db.$queryRaw`SELECT * FROM "CashShiftSession" ORDER BY "id"`,shifts);assert.equal((await db.$queryRaw`SELECT COUNT(*)::int n FROM "AiReaderJob"`)[0].n,jobs);assert.equal((await db.$queryRaw`SELECT to_regclass(format('%I.%I',current_schema(),'PosInvoiceBackgroundTask'))::text relation`)[0].relation,null);
